<script setup lang="ts">
import {reactive,ref,watch} from 'vue'
import {ElMessage,type FormInstance} from 'element-plus'
import type {Row,RequestPayload} from '../api/types'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import {post,put} from '../api/http'
import {useMutation,today} from '../composables/useResource'
const props=defineProps<{modelValue:boolean;record?:Row}>(),emit=defineEmits<{'update:modelValue':[boolean];saved:[]}>()
const auth=useAuth(),formRef=ref<FormInstance>(),form=reactive<RequestPayload>({project_id:'',required_date:today(),note:'',items:[]})
const {saving,run}=useMutation()
const add=()=>form.items.push({material_id:'',quantity:1,unit_price:'0'})
watch(()=>props.modelValue,open=>{if(open){form.project_id=props.record?.project_id||'';form.required_date=props.record?.required_date||today();form.note=props.record?.note||'';form.items=props.record?.items?.map((r:Row)=>({material_id:r.material_id,quantity:Number(r.quantity),unit_price:String(r.unit_price)}))||[];if(!form.items.length)add();formRef.value?.clearValidate()}})
function materialChanged(index:number){const m=auth.catalog.materials.find(r=>r.id===form.items[index]?.material_id);if(m)form.items[index]!.unit_price=String(m.reference_price??'0')}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;if(!form.items.length||form.items.some(i=>!i.material_id||!Number.isFinite(Number(i.quantity))||Number(i.quantity)<=0||!Number.isFinite(Number(i.unit_price))||Number(i.unit_price)<0||String(i.unit_price).trim()==='')){ElMessage.warning('请添加材料并填写有效的数量及预估单价');return}if(new Set(form.items.map(i=>String(i.material_id))).size!==form.items.length){ElMessage.warning('同一材料不可重复，请合并数量');return}if(await run(()=>props.record?.id?put(`/requests/${props.record.id}`,form):post('/requests',form),'申请草稿已保存')){emit('update:modelValue',false);emit('saved')}}
const isMobile=useMediaQuery()
</script>
<template><el-dialog :model-value="modelValue" :title="record?'编辑采购申请':'新建采购申请'" width="960px" :close-on-click-modal="false" destroy-on-close @update:model-value="emit('update:modelValue',$event)"><el-form ref="formRef" :model="form" label-position="top"><div class="form-grid"><el-form-item label="所属项目" prop="project_id" :rules="[{required:true,message:'请选择所属项目'}]"><el-select v-model="form.project_id" filterable placeholder="选择项目"><el-option v-for="p in auth.catalog.projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="要求到货日期" prop="required_date" :rules="[{required:true,message:'请选择需求日期'}]"><el-date-picker v-model="form.required_date" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></div><div class="subheading"><h3>材料需求明细</h3><el-button type="primary" plain size="small" @click="add">＋ 添加材料</el-button></div><div v-if="isMobile" class="mobile-form-lines"><section v-for="(row,index) in form.items" :key="index" class="mobile-form-line"><div class="subheading"><h3>材料 {{index+1}}</h3><el-button type="danger" plain :aria-label="`删除材料 ${index+1}`" @click="form.items.splice(index,1)">删除</el-button></div><el-form-item label="材料"><el-select v-model="row.material_id" filterable placeholder="请选择材料" @change="materialChanged(index)"><el-option v-for="m in auth.catalog.materials" :key="m.id" :label="`${m.name} · ${m.specification||m.unit}`" :value="m.id"/></el-select></el-form-item><p class="field-hint">单位：{{auth.catalog.materials.find(m=>m.id===row.material_id)?.unit||'—'}}</p><el-form-item label="需求数量"><el-input-number v-model="row.quantity" :min="0.001" :precision="3" controls-position="right" style="width:100%"/></el-form-item><el-form-item label="预估单价（元）"><el-input v-model="row.unit_price" inputmode="decimal"/></el-form-item></section></div><el-table v-else :data="form.items" border><el-table-column label="材料" min-width="230"><template #default="{row,$index}"><el-select v-model="row.material_id" filterable placeholder="请选择材料" @change="materialChanged($index)"><el-option v-for="m in auth.catalog.materials" :key="m.id" :label="`${m.name} · ${m.specification||m.unit}`" :value="m.id"/></el-select></template></el-table-column><el-table-column label="单位" width="70"><template #default="{row}">{{auth.catalog.materials.find(m=>m.id===row.material_id)?.unit||'—'}}</template></el-table-column><el-table-column label="需求数量" width="180"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0.001" :precision="3" controls-position="right" style="width:100%"/></template></el-table-column><el-table-column label="预估单价（元）" min-width="150"><template #default="{row}"><el-input v-model="row.unit_price" inputmode="decimal"/></template></el-table-column><el-table-column label="操作" width="70"><template #default="{$index}"><el-button link type="danger" @click="form.items.splice($index,1)">删除</el-button></template></el-table-column></el-table><p class="field-hint">保存后由服务端计算申请金额。草稿保存后可在详情提交审批。</p><el-form-item label="申请说明" class="mt"><el-input v-model="form.note" type="textarea" :rows="3" maxlength="1000" show-word-limit placeholder="说明采购用途、质量要求及现场需求"/></el-form-item></el-form><template #footer><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></template></el-dialog></template>
